INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'inspire', 'v.', '/ɪnˈspaɪə/', '启发;激励;赋予灵感', 'Nature can inspire an artist to create something new.', '大自然能启发艺术家创作新作品。', 'Meeting the Muse', 1, 0, 'senior', 'wordlist', 'elective1', 'U4', 'inspire an artist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'inspiration', 'n.', '/ˌɪnspəˈreɪʃn/', '灵感;启发;鼓舞人心的人或事', 'For many artists, childhood is a rich source of inspiration.', '对许多艺术家来说,童年是丰富的灵感来源。', 'Meeting the Muse', 2, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a source of inspiration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'artist', 'n.', '/ˈɑːtɪst/', '艺术家;画家', 'The famous artist found his ideas in his children''s toys.', '这位著名艺术家从孩子的玩具里找到了创意。', 'Meeting the Muse', 3, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a famous artist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'create', 'v.', '/kriˈeɪt/', '创造;创作', 'Every artist''s wish is to create something that expresses an idea.', '每位艺术家的心愿都是创作能表达某种思想的作品。', 'Meeting the Muse', 4, 0, 'senior', 'wordlist', 'elective1', 'U4', 'create something', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'creation', 'n.', '/kriˈeɪʃn/', '作品;创作;创造', 'With new tools, we can take part in the creation of art.', '借助新工具,我们能参与艺术的创作。', 'Meeting the Muse', 5, 0, 'senior', 'wordlist', 'elective1', 'U4', 'take part in creation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'creative', 'adj.', '/kriˈeɪtɪv/', '有创造力的;创造性的', 'Technology helps more people explore their creative side.', '科技帮助更多人发掘自己的创造力。', 'Meeting the Muse', 6, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a creative mind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'express', 'v.', '/ɪkˈspres/', '表达;表露', 'People have used art to express their thoughts for thousands of years.', '数千年来,人们一直用艺术表达自己的思想。', 'Meeting the Muse', 7, 0, 'senior', 'wordlist', 'elective1', 'U4', 'express an idea', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'expression', 'n.', '/ɪkˈspreʃn/', '表达;表情;表达方式', 'Tan Dun believes music carries a universal expression of the human spirit.', '谭盾认为音乐承载着人类精神的普遍表达。', 'Meeting the Muse', 8, 0, 'senior', 'wordlist', 'elective1', 'U4', 'universal expression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'influence', 'n./v.', '/ˈɪnfluəns/', '影响;影响力;对……产生影响', 'His music mixes Chinese traditions with Western influences.', '他的音乐把中国传统与西方影响融合在一起。', 'Meeting the Muse', 9, 0, 'senior', 'wordlist', 'elective1', 'U4', 'Western influences', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'passion', 'n.', '/ˈpæʃn/', '热情;激情;酷爱', 'Yang Liping''s passion is dancing, and her dances come from folk traditions.', '杨丽萍的热爱是舞蹈,她的舞蹈源自民间传统。', 'Meeting the Muse', 10, 0, 'senior', 'wordlist', 'elective1', 'U4', 'one''s passion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'admire', 'v.', '/ədˈmaɪə/', '钦佩;欣赏;赞赏', 'The Dai people admire the peacock as a symbol of natural beauty.', '傣族人把孔雀视为自然之美而加以欣赏。', 'Meeting the Muse', 11, 0, 'senior', 'wordlist', 'elective1', 'U4', 'admire the peacock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'represent', 'v.', '/ˌreprɪˈzent/', '代表;象征;表现', 'In the dance, the peacock is said to represent the beauty of nature.', '在这支舞里,孔雀被认为象征着自然之美。', 'Meeting the Muse', 12, 0, 'senior', 'wordlist', 'elective1', 'U4', 'represent beauty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tradition', 'n.', '/trəˈdɪʃn/', '传统;惯例', 'Her dances grow out of the tradition of her own people.', '她的舞蹈是从本民族的传统中生长出来的。', 'Meeting the Muse', 13, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a long tradition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'traditional', 'adj.', '/trəˈdɪʃənl/', '传统的;惯例的', 'The dancer draws on the traditional belief of the Dai people.', '这位舞者借鉴了傣族人的传统信仰。', 'Meeting the Muse', 14, 0, 'senior', 'wordlist', 'elective1', 'U4', 'traditional belief', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'belief', 'n.', '/bɪˈliːf/', '信念;信仰;看法', 'His art comes from a deep belief in the power of nature.', '他的艺术源于对自然之力的坚定信念。', 'Meeting the Muse', 15, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a strong belief', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'compose', 'v.', '/kəmˈpəʊz/', '创作(乐曲);组成;构成', 'Tan Dun is widely known for composing music for famous films.', '谭盾因为著名电影作曲而广为人知。', 'Meeting the Muse', 16, 0, 'senior', 'wordlist', 'elective1', 'U4', 'compose music', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'composer', 'n.', '/kəmˈpəʊzə/', '作曲家', 'The Chinese composer tells stories through a mix of sounds.', '这位中国作曲家通过混合各种声音来讲述故事。', 'Meeting the Muse', 17, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a Chinese composer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'universal', 'adj.', '/ˌjuːnɪˈvɜːsl/', '普遍的;通用的;全体的', 'He hopes his music has a universal meaning for the whole world.', '他希望自己的音乐对全世界都有普遍的意义。', 'Meeting the Muse', 18, 0, 'senior', 'wordlist', 'elective1', 'U4', 'universal expression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spirit', 'n.', '/ˈspɪrɪt/', '精神;心灵;情绪', 'Great art often speaks to the human spirit.', '伟大的艺术常常能触动人类的精神。', 'Meeting the Muse', 19, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the human spirit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sculpture', 'n.', '/ˈskʌlptʃə/', '雕塑;雕塑作品', 'His large sculpture of a duck is on display all over the world.', '他那座巨大的鸭子雕塑在世界各地展出。', 'Meeting the Muse', 20, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a large sculpture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'display', 'n./v.', '/dɪˈspleɪ/', '展览;展示;陈列', 'Some famous paintings are rarely on display to the public.', '一些名画很少向公众展出。', 'Meeting the Muse', 21, 0, 'senior', 'wordlist', 'elective1', 'U4', 'on display', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'landscape', 'n.', '/ˈlændskeɪp/', '风景;景观;风景画', 'The huge fish was set among the beautiful landscape of a water town.', '那条巨大的鱼被安放在水乡的美丽景观之中。', 'Meeting the Muse', 22, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a beautiful landscape', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'generation', 'n.', '/ˌdʒenəˈreɪʃn/', '一代人;一代', 'The folk tale had been passed down through the generations.', '这个民间故事代代相传。', 'Meeting the Muse', 23, 0, 'senior', 'wordlist', 'elective1', 'U4', 'passed down through the generations', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'exhibition', 'n.', '/ˌeksɪˈbɪʃn/', '展览;展览会', 'A new exhibition on abstract art is on at the museum this week.', '本周博物馆正在举办一场抽象艺术展。', 'Meeting the Muse', 24, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an art exhibition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impression', 'n.', '/ɪmˈpreʃn/', '印象;感想', 'Which artwork makes the greatest impression on you?', '哪件艺术品给你的印象最深?', 'Meeting the Muse', 25, 0, 'senior', 'wordlist', 'elective1', 'U4', 'make an impression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'abstract', 'adj.', '/ˈæbstrækt/', '抽象(派)的;抽象的', 'Abstract art does not always show real objects.', '抽象艺术并不总是描绘真实的物体。', 'Meeting the Muse', 26, 0, 'senior', 'wordlist', 'elective1', 'U4', 'abstract art', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'contrast', 'n.', '/ˈkɒntrɑːst/', '反差;对比;对照', 'The artist created a strong contrast between light and dark.', '这位艺术家在明暗之间制造了强烈的对比。', 'Meeting the Muse', 27, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a strong contrast', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'innovative', 'adj.', '/ˈɪnəvətɪv/', '创新的;新颖的', 'She uses innovative methods to make her installations.', '她用创新的方法来制作她的装置作品。', 'Meeting the Muse', 28, 0, 'senior', 'wordlist', 'elective1', 'U4', 'innovative methods', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'innovation', 'n.', '/ˌɪnəˈveɪʃn/', '革新;创新', 'We discussed the innovation behind these new art forms.', '我们讨论了这些新艺术形式背后的创新。', 'Meeting the Muse', 29, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the innovation behind it', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'trend', 'n.', '/trend/', '趋势;潮流;动向', 'Digital painting has become a new trend in the art world.', '数字绘画已成为艺术界的一种新潮流。', 'Meeting the Muse', 30, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a new trend', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distinct', 'adj.', '/dɪˈstɪŋkt/', '清晰的;截然不同的;明显的', 'New tools make the line between art and technology less distinct.', '新工具让艺术与科技之间的界限不再那么分明。', 'Meeting the Muse', 31, 0, 'senior', 'wordlist', 'elective1', 'U4', 'less distinct', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'digital', 'adj.', '/ˈdɪdʒɪtl/', '数字的;数码的', 'Millions of people have enjoyed a digital version of the old painting.', '数百万人欣赏过这幅古画的数字版本。', 'Meeting the Muse', 32, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a digital version', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'version', 'n.', '/ˈvɜːʃn/', '版本;译本;说法', 'The museum showed a moving version of the famous scroll.', '博物馆展出了这幅名卷的动态版本。', 'Meeting the Muse', 33, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a digital version', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'accessible', 'adj.', '/əkˈsesəbl/', '可接触到的;易理解的;可使用的', 'Technology has made art more accessible to ordinary people.', '科技让艺术对普通人来说更容易接触。', 'Meeting the Muse', 34, 0, 'senior', 'wordlist', 'elective1', 'U4', 'more accessible', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'combination', 'n.', '/ˌkɒmbɪˈneɪʃn/', '结合;组合;混合', 'His style is a combination of Chinese and Western ideas.', '他的风格是中西方思想的结合。', 'Meeting the Muse', 35, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a combination of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advance', 'n./v.', '/ədˈvɑːns/', '进步;进展;前进', 'Technological advances have changed the art world greatly.', '科技的进步极大地改变了艺术界。', 'Meeting the Muse', 36, 0, 'senior', 'wordlist', 'elective1', 'U4', 'technological advances', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'motion', 'n.', '/ˈməʊʃn/', '动;运动;移动', 'These sights set his idea for the artwork in motion.', '这些景象让他创作这件作品的想法开始萌动。', 'Meeting the Muse', 37, 0, 'senior', 'wordlist', 'elective1', 'U4', 'set in motion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'quote', 'n.', '/kwəʊt/', '引文;引语', 'The article used a quote from the artist about his own work.', '文章引用了这位艺术家谈论自己作品的一句话。', 'Meeting the Muse', 38, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a famous quote', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'folk', 'adj.', '/fəʊk/', '民间的;民俗的', 'His inspiration came from old Chinese folk tales.', '他的灵感来自古老的中国民间故事。', 'Meeting the Muse', 39, 0, 'senior', 'wordlist', 'elective1', 'U4', 'folk tales', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tale', 'n.', '/teɪl/', '故事;传说', 'The old tale about a fish jumping the Dragon Gate inspired him.', '鱼跃龙门的古老传说给了他灵感。', 'Meeting the Muse', 40, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an old tale', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wire', 'n.', '/ˈwaɪə/', '金属丝;电线', 'The map was made entirely of wire and cables.', '这幅地图完全由金属丝和电缆制成。', 'Meeting the Muse', 41, 0, 'senior', 'wordlist', 'elective1', 'U4', 'made of wire', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'literally', 'adv.', '/ˈlɪtərəli/', '确实地;真正地;字面上地', 'Visitors could literally change the colours of the artwork with their phones.', '参观者真的能用手机改变这件作品的颜色。', 'Meeting the Muse', 42, 0, 'senior', 'wordlist', 'elective1', 'U4', 'interact with it literally', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'grateful', 'adj.', '/ˈɡreɪtfl/', '感激的;感谢的', 'Yang Liping feels grateful for the years she spent in Yunnan.', '杨丽萍对自己在云南度过的岁月心怀感激。', 'Meeting the Muse', 43, 0, 'senior', 'wordlist', 'elective1', 'U4', 'feel grateful', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'astonishing', 'adj.', '/əˈstɒnɪʃɪŋ/', '令人惊讶的;惊人的', 'It is astonishing to see a world map made entirely of cables.', '看到一幅完全由电缆做成的世界地图,真是令人惊叹。', 'Meeting the Muse', 44, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an astonishing sight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'breathtaking', 'adj.', '/ˈbreθteɪkɪŋ/', '惊人的;激动人心的;令人屏息的', 'The installation named Superhighway is truly breathtaking.', '那件名为《超级高速公路》的装置作品着实令人叹为观止。', 'Meeting the Muse', 45, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a breathtaking installation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fascinate', 'v.', '/ˈfæsɪneɪt/', '使着迷;深深吸引', 'The floating lights at night fascinate every visitor.', '夜里漂浮的灯光让每位参观者着迷。', 'Meeting the Muse', 46, 0, 'senior', 'wordlist', 'elective1', 'U4', 'fascinate visitors', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u4.01', '①to do 作表语(主语为 wish/aim/plan/job 等,表示打算或目的)', 'A2', 11, '外研社版选择性必修第一册 U4 — 主语是 wish/dream/aim/goal/plan/job/duty/task/hope/purpose 等表''意图、目标''的名词时,be 后用动词不定式作表语,说明''要做的事'',如 Every artist''s wish is to create something。', 1, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u4.02', '②doing(-ing 形式)作表语(主语是引起感受的事物)', 'A2', 11, '外研社版选择性必修第一册 U4 — 当主语是引起某种感受的事物、事件或作品时,be 后用 -ing 形式作表语,如 The film is amazing / The exhibition is exciting,意思是''令人……的''。', 2, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u4.03', '③done(-ed 形式)作表语(主语是感受的承受者)+ -ing 与 -ed 对比', 'A2', 11, '外研社版选择性必修第一册 U4 — 当主语是体会到某种感受的人(或处于某种状态)时,be/feel 后用 -ed 形式作表语,如 I am amazed / The window is broken;与 -ing 形成对比:事物用 -ing,人用 -ed。', 3, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Every artist''s wish is ____ something that expresses an idea.', 'to create', 'creating', 'created', 'create', 'A', '主语 wish 表意图,be 后用不定式说明''要做的事''→ to create。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'My biggest dream has always been ____ a painting that moves people.', 'painting', 'to paint', 'painted', 'paints', 'B', '主语 dream 表目标,表语用不定式 → to paint。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Tan Dun''s goal as a composer is ____ Chinese and Western sounds.', 'combining', 'combined', 'to combine', 'combines', 'C', '主语 goal 表目的,表语用不定式 → to combine。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The whole point of the show is ____ young artists to the public.', 'introducing', 'introduced', 'introduces', 'to introduce', 'D', '主语 point 表目的,表语用不定式 → to introduce。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Her plan for next year is ____ a series of folk paintings.', 'to produce', 'producing', 'produced', 'produces', 'A', 'plan + for next year 表将来打算,表语用不定式 → to produce。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The first step in painting is ____ the main idea clearly in your mind.', 'planning', 'to plan', 'planned', 'plans', 'B', '主语 step 表要做的步骤,表语用不定式 → to plan。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'His aim is ____ the beauty of nature through his dance.', 'showing', 'shown', 'to show', 'shows', 'C', '主语 aim 表目的,表语用不定式 → to show。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The artist''s hope is ____ feelings that words cannot describe.', 'expressing', 'expressed', 'expresses', 'to express', 'D', '主语 hope 表愿望,表语用不定式 → to express。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Our task today is ____ an artwork that we really admire.', 'to describe', 'describing', 'described', 'describes', 'A', '主语 task 表要完成的事,表语用不定式 → to describe。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The purpose of the audio guide is ____ the message of each painting.', 'explaining', 'to explain', 'explained', 'explains', 'B', '主语 purpose 表目的,表语用不定式 → to explain。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Yang Liping''s wish was ____ the special beauty of the Dai women.', 'celebrating', 'celebrated', 'to celebrate', 'celebrates', 'C', '主语 wish 表意图,表语用不定式 → to celebrate。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The next step for the museum is ____ the old scroll in a digital form.', 'presenting', 'presented', 'presents', 'to present', 'D', '主语 step 表要做的步骤,表语用不定式 → to present。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'An artist''s first job is ____ the world around them with fresh eyes.', 'to notice', 'noticing', 'noticed', 'notices', 'A', '主语 job 表职责,表语用不定式 → to notice。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The main goal of the festival is ____ new art forms with the public.', 'sharing', 'to share', 'shared', 'shares', 'B', '主语 goal 表目的,表语用不定式 → to share。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'His real challenge was ____ light and shadow in a single image.', 'capturing', 'captured', 'to capture', 'captures', 'C', '主语 challenge 表要克服的任务,表语用不定式 → to capture。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The duty of a good art teacher is ____ each student''s creative side.', 'inspiring', 'inspired', 'inspires', 'to inspire', 'D', '主语 duty 表职责,表语用不定式 → to inspire。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'My only wish before the show closes is ____ the famous painting in person.', 'to see', 'seeing', 'seen', 'sees', 'A', '主语 wish 表愿望,表语用不定式 → to see。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'Hofman''s idea was ____ a giant duck that everyone would love.', 'designing', 'to design', 'designed', 'designs', 'B', '主语 idea 表打算做的事,表语用不定式 → to design。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'The aim of the project was ____ data in the way an artist uses paint.', 'using', 'used', 'to use', 'uses', 'C', '主语 aim 表目的,表语用不定式 → to use。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.01'), 'A sculptor''s task is often ____ a living shape out of cold stone.', 'building', 'built', 'builds', 'to build', 'D', '主语 task 表要完成的事,表语用不定式 → to build。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The new exhibition on abstract art is really ____.', 'amazing', 'amazed', 'amaze', 'to amaze', 'A', '主语 exhibition 是引起感受的事物,表语用 -ing → amazing。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Her performance on stage was so ____ that nobody moved.', 'moved', 'moving', 'move', 'to move', 'B', '主语 performance 引起感动,表语用 -ing → moving。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The story behind the painting is quite ____.', 'fascinated', 'fascinate', 'fascinating', 'to fascinate', 'C', '主语 story 是引起兴趣的事物,表语用 -ing → fascinating。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Tan Dun''s music for the film is truly ____.', 'inspired', 'inspire', 'to inspire', 'inspiring', 'D', '主语 music 给人启发,表语用 -ing → inspiring。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The light show at night is absolutely ____.', 'astonishing', 'astonished', 'astonish', 'to astonish', 'A', '主语 light show 是令人惊叹的事物,表语用 -ing → astonishing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'For me, the long lecture on folk art was rather ____.', 'bored', 'boring', 'bore', 'to bore', 'B', '主语 lecture 是令人乏味的事物,表语用 -ing → boring。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The colours in this artwork are very ____ to the eye.', 'pleased', 'please', 'pleasing', 'to please', 'C', '主语 colours 是令人愉悦的事物,表语用 -ing → pleasing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The sudden change of scene in the play was ____.', 'surprised', 'surprise', 'to surprise', 'surprising', 'D', '主语 change 是令人意外的事,表语用 -ing → surprising。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Walking around the huge museum all day can be ____.', 'tiring', 'tired', 'tire', 'to tire', 'A', '主语(walking 这件事)使人疲惫,表语用 -ing → tiring。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The way the artist mixes ideas is a little ____ at first.', 'confused', 'confusing', 'confuse', 'to confuse', 'B', '主语 way 是令人困惑的事物,表语用 -ing → confusing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The final result of the project was deeply ____.', 'satisfied', 'satisfy', 'satisfying', 'to satisfy', 'C', '主语 result 令人满意,表语用 -ing → satisfying。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The price of some of the tickets is honestly ____.', 'shocked', 'shock', 'to shock', 'shocking', 'D', '主语 price 令人震惊,表语用 -ing → shocking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Soft music playing in the gallery is quite ____.', 'relaxing', 'relaxed', 'relax', 'to relax', 'A', '主语 music 使人放松,表语用 -ing → relaxing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The film about the young painter is very ____.', 'touched', 'touching', 'touch', 'to touch', 'B', '主语 film 令人感动,表语用 -ing → touching。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Sadly, the ending of the show was a bit ____.', 'disappointed', 'disappoint', 'disappointing', 'to disappoint', 'C', '主语 ending 令人失望,表语用 -ing → disappointing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Some of the dark sculptures in the hall look ____.', 'frightened', 'frighten', 'to frighten', 'frightening', 'D', '主语 sculptures 是令人害怕的事物,表语用 -ing → frightening。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'Her kind words about my drawing were really ____.', 'encouraging', 'encouraged', 'encourage', 'to encourage', 'A', '主语 words 给人鼓舞,表语用 -ing → encouraging。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The idea of painting with data is rather ____.', 'excited', 'exciting', 'excite', 'to excite', 'B', '主语 idea 令人兴奋,表语用 -ing → exciting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'The view from the top of the giant sculpture is ____.', 'stunned', 'stun', 'stunning', 'to stun', 'C', '主语 view 令人惊艳,表语用 -ing → stunning。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.02'), 'This abstract painting is far more ____ than I expected.', 'interested', 'interest', 'to interest', 'interesting', 'D', '主语 painting 是引起兴趣的事物,表语用 -ing → interesting。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'I am totally ____ by the painting called Storm.', 'amazed', 'amazing', 'amaze', 'to amaze', 'A', '主语 I 是感受的承受者,表语用 -ed → amazed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The visitors were deeply ____ by the young artist''s story.', 'moving', 'moved', 'move', 'to move', 'B', '主语 visitors 是被感动的人,表语用 -ed → moved。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'After the visit, she was really ____ in abstract art.', 'interesting', 'interest', 'interested', 'to interest', 'C', '主语 she 体会到兴趣,表语用 -ed → interested。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'After the long tour, the children were quite ____.', 'tiring', 'tire', 'to tire', 'tired', 'D', '主语 children 感到疲惫,表语用 -ed → tired。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Richard was honestly ____ by the over-priced tickets.', 'shocked', 'shocking', 'shock', 'to shock', 'A', '主语 Richard 受到震惊,表语用 -ed → shocked。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Everyone in the hall was ____ by the breathtaking installation.', 'fascinating', 'fascinated', 'fascinate', 'to fascinate', 'B', '主语 everyone 被吸引,表语用 -ed → fascinated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The teacher was very ____ with the students'' creative work.', 'pleasing', 'please', 'pleased', 'to please', 'C', '主语 teacher 感到满意,表语用 -ed → pleased。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'At first I felt a bit ____ by the strange shapes.', 'confusing', 'confuse', 'to confuse', 'confused', 'D', '主语 I 感到困惑,feel 后用 -ed → confused。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'We were all ____ by the beauty of the digital scroll.', 'impressed', 'impressing', 'impress', 'to impress', 'A', '主语 we 留下深刻印象,表语用 -ed → impressed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The audience seemed ____ during the slow parts of the film.', 'boring', 'bored', 'bore', 'to bore', 'B', '主语 audience 感到无聊,表语用 -ed → bored。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Amy was so ____ about the new exhibition that she told all her friends.', 'exciting', 'excite', 'excited', 'to excite', 'C', '主语 Amy 感到兴奋,表语用 -ed → excited。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'He was honestly ____ when his work was chosen for the show.', 'astonishing', 'astonish', 'to astonish', 'astonished', 'D', '主语 he 感到惊讶,表语用 -ed → astonished。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The crowd was ____ to learn that a computer had made the painting.', 'surprised', 'surprising', 'surprise', 'to surprise', 'A', '主语 crowd 感到意外,表语用 -ed → surprised。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The girl looked ____ by the kind comments on her drawing.', 'touching', 'touched', 'touch', 'to touch', 'B', '主语 girl 被打动,表语用 -ed → touched。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Some teachers are ____ that computers may one day create art.', 'worrying', 'worry', 'worried', 'to worry', 'C', '主语 teachers 感到担忧,表语用 -ed → worried。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'The students were warmly ____ by their teacher to keep trying.', 'encouraging', 'encourage', 'to encourage', 'encouraged', 'D', '主语 students 受到鼓励,表语用 -ed → encouraged。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Sadly, the fans were ____ when the show was cancelled.', 'disappointed', 'disappointing', 'disappoint', 'to disappoint', 'A', '主语 fans 感到失望,表语用 -ed → disappointed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'Standing alone in the dark gallery, the boy felt ____.', 'frightening', 'frightened', 'frighten', 'to frighten', 'B', '主语 boy 感到害怕,feel 后用 -ed → frightened。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'After finishing the huge mural, the painter felt deeply ____.', 'satisfying', 'satisfy', 'satisfied', 'to satisfy', 'C', '主语 painter 感到满足,feel 后用 -ed → satisfied。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U4' AND code='fe1u4.03'), 'We were truly ____ by the artist''s passion for his motherland.', 'inspiring', 'inspire', 'to inspire', 'inspired', 'D', '主语 we 受到鼓舞,表语用 -ed → inspired。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Hofman and His Floating Fish', 'Florentijn Hofman is a Dutch artist whose large sculptures are shown all over the world. One way for him to find new ideas is turning to his own children''s toys. These simple objects have given him ideas for his animal sculptures, such as the famous Rubber Duck. A more recent work is the huge Floating Fish, which was set among the beautiful landscape of a Chinese water town. Hofman''s inspiration for this fish came from old Chinese folk tales that had been passed down through the generations. He was especially interested in the story about a fish jumping through the Dragon Gate. The story came to life for him when he visited the town and saw how people really lived there. During his stay, he watched the fish being fed by local people and noticed others carved on the walls. These everyday sights set his idea in motion and led to a brand-new artwork.', '记叙·艺术家与灵感', 154, '[{"q":"Where does Hofman often get ideas for his animal sculptures?","answer":"A","options":["From the toys his children play with.","From paintings in foreign museums.","From his old school lessons.","From photographs of busy cities."],"explanation":"原文说他常从孩子的玩具中找灵感,故选''孩子玩的玩具''。"},{"q":"What gave Hofman the idea for the Floating Fish?","answer":"B","options":["A short trip to the seaside.","Traditional folk stories handed down over many years.","A new book about modern science.","A song he heard on the radio."],"explanation":"原文 ''old Chinese folk tales that had been passed down through the generations'' 的转述。"},{"q":"What happened when Hofman visited the water town?","answer":"A","options":["Seeing local life made the old story feel real to him.","He decided to give up making art.","He sold all of his earlier sculptures.","He moved away and never returned."],"explanation":"原文 ''The story came to life for him when he visited the town'' 的转述。"}]'::jsonb, '[{"word":"sculpture","cn":"雕塑"},{"word":"folk tale","cn":"民间故事"},{"word":"set in motion","cn":"使……开始"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Tan Dun and a World of Sound', 'Tan Dun is one of China''s best-known composers. He once said that there is no territory in the world of music, meaning that music belongs to everyone. He is most widely known for composing the music for the film Crouching Tiger, Hidden Dragon and for the 2008 Beijing Olympics. To listen to Tan''s music is to experience a mix of Chinese musical traditions and Western influences. Since his very first opera, he has used a combination of Chinese sounds and sounds from all over the world to tell stories. Tan believes that Chinese music should carry a universal expression of the human spirit, so that it can be recognised and enjoyed by the whole world. His works show that old traditions and new ideas can live happily side by side. For Tan, the real power of music is its ability to cross every border and speak to people everywhere.', '说明·作曲家与灵感', 149, '[{"q":"What does Tan Dun mean by saying there is no territory in music?","answer":"B","options":["Music must follow only Chinese rules.","Music has no borders and belongs to everyone.","Only a few experts can understand music.","Western music is better than Chinese music."],"explanation":"原文 ''music belongs to everyone'' 的转述。"},{"q":"How would you describe Tan Dun''s musical style?","answer":"C","options":["Only traditional Chinese opera.","Pure Western pop music.","A mixture of Chinese and Western musical ideas.","Music with no Chinese parts at all."],"explanation":"原文 ''a mix of Chinese musical traditions and Western influences'' 的转述。"},{"q":"What does Tan Dun hope his music can do?","answer":"D","options":["Be enjoyed only inside China.","Take the place of all Western music.","Be quickly forgotten by listeners.","Reach and move people everywhere, beyond borders."],"explanation":"原文 ''cross every border and speak to people everywhere'' 的转述。"}]'::jsonb, '[{"word":"composer","cn":"作曲家"},{"word":"universal","cn":"普遍的"},{"word":"combination","cn":"结合"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Peacock Princess', 'Yang Liping''s passion is dancing. After winning a national competition in 1986 with her Spirit of the Peacock dance, she became known as the Peacock Princess. The inspiration for her famous dances has come from the years she spent in Xishuangbanna, in Yunnan Province. Yang feels very grateful for that time, because it gave her a chance to go deeper into the lives of various groups of people there. Among them, the Dai people especially admire the peacock, which they believe represents the beauty of nature. Yang loves the dance style of the Dai people, and it gives her a great deal of inspiration. Her dancing grows out of their traditional beliefs and aims to bring out the natural beauty of Dai women. In this way, Yang shows that the richest inspiration often comes not from somewhere far away, but from one''s own roots and home.', '记叙·舞者与灵感', 146, '[{"q":"Why is Yang Liping called the Peacock Princess?","answer":"A","options":["Because her prize-winning dance was about the peacock.","Because she keeps peacocks at her home.","Because she was born into a royal family.","Because she paints pictures of peacocks."],"explanation":"原文她以《雀之灵》获奖后得名,故选与获奖孔雀舞相关的一项。"},{"q":"Where does Yang Liping''s inspiration mainly come from?","answer":"B","options":["Books she read about Western dance.","Her years living among the people of Yunnan.","A famous teacher in the capital city.","Films she watched when she was a child."],"explanation":"原文 ''the years she spent in Xishuangbanna, in Yunnan Province'' 的转述。"},{"q":"What does the passage suggest about inspiration?","answer":"C","options":["It can only be found in foreign countries.","It has nothing to do with local traditions.","It often comes from one''s own home and roots.","It is impossible for ordinary people to find."],"explanation":"末句强调灵感常来自自己的根与家乡。"}]'::jsonb, '[{"word":"passion","cn":"热爱"},{"word":"grateful","cn":"感激的"},{"word":"represent","cn":"象征"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'When Art Meets Technology', 'Think about the word ''art''. What comes to your mind? Perhaps it is a painting in a famous museum, or maybe it is a dancing pattern of lights. The artworks by American artist Janet Echelman look like colourful floating clouds when they are lit up at night. Visitors to one of her works in Vancouver could not only enjoy looking at it; they could also take part in it. Using their phones, they were able to control its colours and patterns themselves. Exhibits like these are certainly new and exciting, but some people still ask whether they are really art. For thousands of years, humans have expressed their ideas through art, using many different tools. Today, technological advances have led to a close combination of art and technology. As a result, art is now more accessible to ordinary people than ever before, and almost anyone can explore their own creative side.', '说明·艺术与科技', 151, '[{"q":"What are Janet Echelman''s artworks compared to at night?","answer":"D","options":["Silent grey stones on the ground.","Old oil paintings on a wall.","Empty and dark city streets.","Bright clouds floating in the air."],"explanation":"原文 ''colourful floating clouds when they are lit up at night'' 的转述。"},{"q":"What could visitors in Vancouver do with their phones?","answer":"A","options":["Change how the artwork''s colours and patterns looked.","Buy the whole artwork at once.","Take the lights home with them.","Turn off the museum''s main power."],"explanation":"原文 ''control its colours and patterns'' 的转述。"},{"q":"According to the passage, how has technology changed art?","answer":"B","options":["It has made art disappear completely.","It has made art easier for ordinary people to reach.","It has stopped people from being creative.","It has made art only for rich collectors."],"explanation":"原文 ''art is now more accessible to ordinary people than ever before'' 的转述。"}]'::jsonb, '[{"word":"accessible","cn":"易接触的"},{"word":"advance","cn":"进步"},{"word":"creative","cn":"有创造力的"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Art for War and Peace', 'Since the earliest cave paintings, humans have shown their art on walls. Bringing artworks together into an exhibition allows all of us to enjoy them and to connect with the artists behind them. Exhibitions can follow many themes, such as a historical period, a place or a trend. One theme that never grows old is war and peace. Throughout history, countless artists have protested against wars and called for peace through their works. Two famous examples are the Spanish artist Pablo Picasso and the Chinese artist Feng Zikai. Picasso painted Guernica after the bombing of a small town, using only a few colours to show the pain of war. Feng Zikai painted scenes of his own country during a hard time, choosing simple images to create a strong contrast. Though the two artists lived far apart and worked in very different styles, their message was the same: people everywhere long for peace.', '说明·主题艺术展', 152, '[{"q":"What does putting artworks into an exhibition allow people to do?","answer":"C","options":["Forget about the artists completely.","Buy the whole museum building.","Enjoy the works and feel a link to their makers.","Paint over the older artworks."],"explanation":"原文 ''enjoy them and to connect with the artists behind them'' 的转述。"},{"q":"What is special about the theme of war and peace?","answer":"D","options":["It is used only by Spanish artists.","It has been banned from all museums.","It is a brand-new idea in art.","It is a subject that artists return to in every age."],"explanation":"原文 ''One theme that never grows old is war and peace'' 的转述。"},{"q":"What did Picasso and Feng Zikai have in common?","answer":"A","options":["They both used art to call for peace.","They painted in exactly the same style.","They lived together in the same town.","They believed war could solve problems."],"explanation":"末句 ''their message was the same: people everywhere long for peace'' 的转述。"}]'::jsonb, '[{"word":"exhibition","cn":"展览"},{"word":"trend","cn":"潮流"},{"word":"contrast","cn":"对比"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Meeting the Girl with a Pearl Earring', 'One of my biggest dreams had always been to see the painting Girl with a Pearl Earring by the Dutch artist Vermeer. That dream finally came true when my family went on a trip last year. When we reached the museum, there were lots of people waiting to enter, and my legs were tired from walking around the city all morning. Still, I was determined to see the painting, which is often called the Mona Lisa of the North. Nobody is really sure who the girl in it was. At last I stood in front of her, and it was amazing to be so close to such a famous work. In the picture, the girl is looking back over her shoulder. Her eyes are wide, and her mouth is slightly parted, as if she is about to speak. Standing there, I would love to have known what she was going to say.', '记叙·看画的经历', 152, '[{"q":"Why was the writer determined to see the painting despite being tired?","answer":"B","options":["A teacher had ordered the writer to go.","Seeing it had long been one of the writer''s dreams.","The writer planned to buy the painting.","The writer wanted to copy it for homework."],"explanation":"原文开头 ''One of my biggest dreams had always been to see the painting'' 的转述。"},{"q":"What is the painting also known as?","answer":"C","options":["An unknown modern drawing.","A painting with no real name.","A northern version of the Mona Lisa.","A picture of the writer''s family."],"explanation":"原文 ''often called the Mona Lisa of the North'' 的转述。"},{"q":"How does the girl in the painting appear?","answer":"D","options":["She is crying very loudly.","She has closed both her eyes.","She is laughing at the viewer.","She seems ready to say something."],"explanation":"原文 ''her mouth is slightly parted, as if she is about to speak'' 的转述。"}]'::jsonb, '[{"word":"determined","cn":"下定决心的"},{"word":"amazing","cn":"令人惊叹的"}]'::jsonb, 2, 'elective1', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Finding Inspiration in Nature', 'Lin Yu has always loved to draw, and her greatest (1)____ is nature. Every weekend she walks in the hills near her home, looking closely at the trees, flowers and birds. She says that even a single leaf can give her a fresh (2)____ for a painting. Last spring, she was so (3)____ by a field of wild flowers that she could not wait to pick up her brush. Back home, she tried to (4)____ their bright colours on paper. At first the painting did not look right, and she felt a little (5)____. But she refused to (6)____. She painted the same scene again and again until she was finally (7)____ with the result. Her art teacher was deeply (8)____ by her hard work and her love of nature. He told the class that the best artists learn to (9)____ the world around them with fresh eyes. For Lin Yu, the message was clear: inspiration is everywhere, as long as you take the time to (10)____.', 167, 2, '[{"q":"1","answer":"A","options":["inspiration","machine","price","noise"],"explanation":"her greatest inspiration 最大的灵感来源。"},{"q":"2","answer":"B","options":["ticket","idea","noise","price"],"explanation":"a fresh idea 新创意。"},{"q":"3","answer":"C","options":["exciting","bored","excited","boring"],"explanation":"主语 she 感到兴奋 → excited(-ed)。"},{"q":"4","answer":"D","options":["sell","forget","lose","capture"],"explanation":"capture their colours 捕捉色彩。"},{"q":"5","answer":"A","options":["disappointed","pleased","proud","glad"],"explanation":"画得不理想 → felt disappointed 失望。"},{"q":"6","answer":"B","options":["sell","quit","sleep","cry"],"explanation":"refused to quit 拒绝放弃。"},{"q":"7","answer":"C","options":["satisfying","boring","satisfied","bored"],"explanation":"主语 she 对结果满意 → satisfied(-ed)。"},{"q":"8","answer":"D","options":["impressing","amazing","boring","impressed"],"explanation":"主语 teacher 留下深刻印象 → impressed(-ed)。"},{"q":"9","answer":"A","options":["observe","throw","sell","lose"],"explanation":"observe the world 观察世界。"},{"q":"10","answer":"B","options":["sleep","look","run","pay"],"explanation":"take the time to look 花时间去看。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'A Visit to the Modern Art Museum', 'Last Sunday, my friend and I went to a new (1)____ of abstract art at the city museum. As soon as we walked in, I was (2)____ by the bright colours on the walls. One large painting was so (3)____ that we stood in front of it for a long time. My friend said the shapes looked a little (4)____ at first, but the more we looked, the more we enjoyed them. A guide explained that abstract art does not always (5)____ real objects; instead, it tries to express feelings. That idea was completely new and very (6)____ to me. Near the exit, there was a modern artwork made entirely of (7)____ and light. It was truly (8)____ to see how the artist had turned cold metal into something beautiful. By the end of the visit, I had a much better (9)____ of what art can be. I left the museum feeling (10)____ and full of new ideas.', 158, 2, '[{"q":"1","answer":"C","options":["machine","garden","exhibition","market"],"explanation":"an exhibition of abstract art 抽象艺术展。"},{"q":"2","answer":"D","options":["amazing","bored","boring","amazed"],"explanation":"主语 I 被惊艳 → amazed(-ed)。"},{"q":"3","answer":"A","options":["moving","moved","quiet","empty"],"explanation":"主语 painting 令人感动 → moving(-ing)。"},{"q":"4","answer":"B","options":["cheap","strange","loud","sweet"],"explanation":"shapes looked strange 形状看着奇怪。"},{"q":"5","answer":"C","options":["eat","sell","show","buy"],"explanation":"does not always show real objects 不总是描绘实物。"},{"q":"6","answer":"D","options":["excited","boring","bored","exciting"],"explanation":"主语 idea 令人兴奋 → exciting(-ing)。"},{"q":"7","answer":"A","options":["wire","water","paper","glass"],"explanation":"made of wire and light 由金属丝和光制成。"},{"q":"8","answer":"B","options":["amazed","amazing","tiring","tired"],"explanation":"形式主语 It,是令人惊叹的事 → amazing(-ing)。"},{"q":"9","answer":"C","options":["price","ticket","understanding","noise"],"explanation":"a better understanding 更深的理解。"},{"q":"10","answer":"D","options":["inspiring","bored","tired","inspired"],"explanation":"主语 I 受到鼓舞 → inspired(-ed)。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Learning Chinese Ink Painting', 'My grandmother is the person (1)____ first taught me Chinese ink painting. She told me it was an art (2)____ done with a soft brush and black ink. At first my lines were shaky, and I almost wanted to (3)____. But Grandma said that painting shows the (4)____ of the person behind the brush, so I should be patient. Little by little, I learned to (5)____ each stroke slowly and carefully. Now ink painting is the hobby (6)____ I enjoy most of all. It makes me feel (7)____ and helps me forget the stress of school. It also (8)____ me to the past, because people have painted this way for thousands of (9)____. Whenever I pick up my brush, I feel proud to be part of such an old (10)____.', 130, 2, '[{"q":"1","answer":"A","options":["who","which","where","when"],"explanation":"the person who 指人作主语。"},{"q":"2","answer":"B","options":["price","form","noise","game"],"explanation":"an art form 一种艺术形式。"},{"q":"3","answer":"C","options":["sell","sleep","quit","run"],"explanation":"wanted to quit 想放弃。"},{"q":"4","answer":"D","options":["price","weather","noise","character"],"explanation":"the character of the person 人的品格。"},{"q":"5","answer":"A","options":["draw","throw","sell","lose"],"explanation":"draw each stroke 画好每一笔。"},{"q":"6","answer":"B","options":["who","that","where","when"],"explanation":"the hobby that I enjoy 指物作宾语。"},{"q":"7","answer":"C","options":["angry","afraid","calm","noisy"],"explanation":"feel calm 感到平静。"},{"q":"8","answer":"D","options":["sells","breaks","loses","connects"],"explanation":"connects me to the past 把我和过去相连。"},{"q":"9","answer":"A","options":["years","minutes","metres","seconds"],"explanation":"thousands of years 数千年。"},{"q":"10","answer":"B","options":["shop","art","game","city"],"explanation":"an old art 古老的艺术。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Art in Everyday Life', 'Art is not only found in museums; it is all (1)____ us in daily life. In some cities, artists paint bright pictures on the holes of old trees, turning a plain street into something (2)____. Others paint flat manhole covers with lovely (3)____ of animals and flowers. There is even an art form (4)____ uses colourful wool to cover lamp posts and railings. These small works often make people smile and (5)____ their day. The artists behind them want to bring beauty to ordinary (6)____. They believe that everyone should be able to (7)____ art, not just those who visit galleries. Many passers-by are pleasantly (8)____ when they suddenly meet such art on their way to work. This kind of street art is becoming a popular (9)____ in many countries. It reminds us that, with a little imagination, almost any corner can become a (10)____ of beauty.', 147, 2, '[{"q":"1","answer":"C","options":["under","behind","around","between"],"explanation":"all around us 在我们周围。"},{"q":"2","answer":"D","options":["empty","silent","cheap","beautiful"],"explanation":"something beautiful 美丽的东西。"},{"q":"3","answer":"A","options":["pictures","prices","noises","tickets"],"explanation":"lovely pictures 可爱的图画。"},{"q":"4","answer":"B","options":["who","that","where","when"],"explanation":"an art form that uses 指物作主语。"},{"q":"5","answer":"C","options":["break","sell","brighten","lose"],"explanation":"brighten their day 点亮他们的一天。"},{"q":"6","answer":"D","options":["prices","machines","tickets","people"],"explanation":"ordinary people 普通人。"},{"q":"7","answer":"A","options":["enjoy","forget","sell","lose"],"explanation":"able to enjoy art 能欣赏艺术。"},{"q":"8","answer":"B","options":["surprising","surprised","bored","boring"],"explanation":"主语 passers-by 感到惊喜 → surprised(-ed)。"},{"q":"9","answer":"C","options":["price","noise","trend","ticket"],"explanation":"a popular trend 流行潮流。"},{"q":"10","answer":"D","options":["price","noise","machine","place"],"explanation":"a place of beauty 美的所在。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Bringing an Old Painting to Life', 'One of China''s most famous paintings shows busy life along a river during the Song Dynasty. Because the original is rarely on (1)____, people once queued for hours just to see it for a few minutes. Thanks to new technology, however, millions more people can now enjoy a digital (2)____ of this work. With the help of 3D animation, viewers can watch the tiny figures (3)____ around and even seem to talk to one another. They can also see the scenes slowly (4)____ from day into night. Standing before the giant screen, I was completely (5)____ by what I saw. The whole experience was far more (6)____ than looking at a still picture. A guide explained that such technology makes old art more (7)____ to young people. I think this is a wonderful (8)____, because it helps more of us connect with the past. Some people (9)____ that machines may change art too much. But for me, seeing this old painting come alive was simply (10)____.', 166, 2, '[{"q":"1","answer":"A","options":["display","holiday","noise","machine"],"explanation":"on display 展出。"},{"q":"2","answer":"B","options":["machine","version","garden","price"],"explanation":"a digital version 数字版本。"},{"q":"3","answer":"C","options":["sleep","sell","move","buy"],"explanation":"watch the figures move 看人物移动。"},{"q":"4","answer":"D","options":["sell","lose","forget","change"],"explanation":"scenes change from day into night 场景从白天变到夜晚。"},{"q":"5","answer":"A","options":["amazed","amazing","bored","boring"],"explanation":"主语 I 被震撼 → amazed(-ed)。"},{"q":"6","answer":"B","options":["excited","exciting","boring","bored"],"explanation":"主语(经历)令人兴奋 → exciting(-ing)。"},{"q":"7","answer":"C","options":["expensive","silent","accessible","empty"],"explanation":"more accessible 更易接触。"},{"q":"8","answer":"D","options":["price","noise","machine","idea"],"explanation":"a wonderful idea 一个好主意。"},{"q":"9","answer":"A","options":["worry","sleep","sell","laugh"],"explanation":"worry that 担心。"},{"q":"10","answer":"B","options":["amazed","amazing","tiring","tired"],"explanation":"主语(这件事)令人惊叹 → amazing(-ing)。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'A Song from an Old Tale', 'My uncle is a (1)____ who writes music for films. Last year he was asked to (2)____ a piece of music for a story about an old fishing village. To find ideas, he read many local folk (3)____ that had been passed down for hundreds of years. One story about a brave fisherman (4)____ him most of all. He spent weeks at the seaside, listening to the waves and the wind, hoping they would give him (5)____. Slowly, the music began to take (6)____ in his mind. He mixed the sound of traditional instruments with a few (7)____ ideas of his own. When the film was shown, the audience was deeply (8)____ by the beautiful music. Many people said the song felt both old and new at the same (9)____. My uncle told me that the best music often comes from listening carefully to the (10)____ around us.', 148, 2, '[{"q":"1","answer":"C","options":["driver","farmer","composer","doctor"],"explanation":"a composer 作曲家。"},{"q":"2","answer":"D","options":["sell","buy","throw","compose"],"explanation":"compose a piece of music 谱写乐曲。"},{"q":"3","answer":"A","options":["tales","prices","tickets","machines"],"explanation":"folk tales 民间故事。"},{"q":"4","answer":"B","options":["sold","inspired","lost","left"],"explanation":"inspired him most 最给他灵感。"},{"q":"5","answer":"C","options":["money","trouble","inspiration","noise"],"explanation":"give him inspiration 给他灵感。"},{"q":"6","answer":"D","options":["money","noise","ticket","shape"],"explanation":"take shape 逐渐成形。"},{"q":"7","answer":"A","options":["innovative","heavy","cold","wet"],"explanation":"innovative ideas 创新的想法。"},{"q":"8","answer":"B","options":["moving","moved","bored","boring"],"explanation":"主语 audience 被感动 → moved(-ed)。"},{"q":"9","answer":"C","options":["price","noise","time","place"],"explanation":"at the same time 同时。"},{"q":"10","answer":"D","options":["prices","tickets","machines","sounds"],"explanation":"the sounds around us 我们周围的声音。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Planning a Museum Visit', '外研社版选择性必修第一册 U4 · dialogue', 3, 'Mia: Hi Jack! Are you free this Saturday? There''s a new art exhibition at the city museum.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Where Artists Find Ideas', '外研社版选择性必修第一册 U4 · passage', 2, 'Where do artists get their ideas? The answer is different for everyone.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Talking about a Sculpture', '外研社版选择性必修第一册 U4 · dialogue', 3, 'Tom: Lily, did you see that huge sculpture in the city square?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Art and Technology', '外研社版选择性必修第一册 U4 · passage', 2, 'Technology is changing the way we enjoy art.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Choosing an Artwork to Write About', '外研社版选择性必修第一册 U4 · dialogue', 3, 'Teacher: For today''s writing task, choose one artwork that makes a strong impression on you.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 A Tip for Finding Inspiration', '外研社版选择性必修第一册 U4 · passage', 2, 'Here is a simple tip for anyone who wants to find their own inspiration.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an Invitation to a School Art Festival(写一封艺术节邀请函)', 'An Invitation to Our School Art Festival', '假设你叫李华,是学校学生会成员。你校将举办一年一度的学生艺术节。请用英语写一封约80词的正式邀请函,邀请你的英语外教 Mr Smith 参加,内容包括:① 艺术节的名称、时间和地点;② 将展出的艺术作品(如绘画、雕塑、用电脑部件做的作品等);③ 礼貌地请他回复确认是否参加。注意:用正式得体的语气。', 'Suppose you are Li Hua, a member of the Students'' Union. Your school is holding its yearly Student Art Festival. Write a formal invitation (about 80 words) to your English teacher, Mr Smith, including: 1) the name, time and place of the festival; 2) the artworks that will be shown (e.g. paintings, sculptures, works made from computer parts); 3) a polite request for him to reply and confirm whether he can come. Use a formal and proper tone.', '["写清活动名称、时间、地点(name, time and place)","介绍将展出的艺术作品(a wide variety of artworks)","礼貌邀请并请求回复(We would be honoured … Please reply to confirm.)","语气正式得体、结构清楚"]'::jsonb, 70, 100, 'Dear Mr Smith, On behalf of the Students'' Union, I am writing to invite you to our yearly Student Art Festival. The festival will be held in the school hall from 12 to 16 May, opening at six o''clock on the first evening. Visitors will be able to enjoy a wide variety of artworks, from paintings and sculptures to creative works made out of computer parts. It would be a great honour to have you with us. Please reply to confirm whether you are able to attend. Yours sincerely, Li Hua', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["On behalf of the Students'' Union, I am writing to invite you to our yearly Student Art Festival.","The festival will be held in the school hall from 12 to 16 May.","Visitors will be able to enjoy a wide variety of artworks, from paintings to works made out of computer parts.","It would be a great honour to have you with us."]'::jsonb, '[{"wrong":"I am writing for invite you to the festival.","correct":"I am writing to invite you to the festival.","note":"表示目的用不定式 to do,不用 for doing。"},{"wrong":"The festival will be hold in the hall.","correct":"The festival will be held in the hall.","note":"被动语态用 be + 过去分词 held。"},{"wrong":"The exhibition is amazed.","correct":"The exhibition is amazing.","note":"主语是引起感受的事物,表语用 -ing 形式 amazing。"}]'::jsonb, '【艺术节邀请函结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U4', '{"title":"不定式 / -ing / -ed 作表语速查","intro":"be 动词后面除了名词、形容词,还可以用三种非谓语形式作表语:to do(说明意图、要做的事)、doing(主语是引起感受的事物)、done(主语是承受感受或处于某种状态的人/物)。判断口诀:看主语——表''打算/目的''的名词后用 to do;事物''令人……''用 -ing;人''感到……''用 -ed。","table":{"headers":["表语形式","用法 / 例句"],"rows":[["to do","主语为 wish/aim/plan/job/dream/goal 等意图名词:Every artist''s wish is to create something."],["doing(-ing)","主语是引起感受的事物/事件:The film is amazing. / The exhibition is exciting."],["done(-ed)","主语是体会感受的人或某种状态:I am amazed. / The window is broken."],["-ing vs -ed","事物用 -ing(令人……),人用 -ed(感到……):The news is surprising. / We are surprised."]]},"specialRules":[{"rule":"主语是 wish/aim/plan/goal/job/duty/hope 等表意图的名词 → be + to do","mark":"Her plan is to paint a series of pictures."},{"rule":"主语是引起情绪的事物 → be + -ing","mark":"The performance was moving.(演出令人感动)"},{"rule":"主语是体会情绪的人 → be/feel + -ed","mark":"The visitors were moved.(参观者被感动)"},{"rule":"interesting/interested、exciting/excited、amazing/amazed 等成对出现,别混","mark":"The story is interesting. / I am interested."}],"why":["-ing 形式本身含''主动、令人……''的意味,所以用来描述''引起感受''的事物;-ed 形式含''被动、受到影响''的意味,所以用来描述''感受到……''的人。一句话里到底用哪个,关键看 be 前面的主语是''施事(事物)''还是''受事(人)''。"],"gaokaoPoints":["interesting/interested 类成对形容词的辨析(看主语是物还是人)——语法填空、单选高频。","wish/aim/plan/job + be + to do 作表语;以及 The + 名词 + is doing/done 的判断。"],"examVsReal":[{"exam":"His job is to teach art.(考试规范:意图名词 + to do)","real":"His job is teaching art.","note":"考试首选不定式;口语里 job/hobby 后也常用 -ing 表''就是做某事''"},{"exam":"I am very interested in it.(考试:人用 -ed)","real":"I''m really into it.","note":"考试用 interested;口语里常用 be into sth 表示''对……很感兴趣''"}]}'::jsonb, 'fltrp');
